using System.Collections.Immutable;
namespace Bed.Editor;

/// <summary>Producer-declared artifact origin. GameOwned means generated by the game from project data, not inferred ownership.</summary>
public sealed class ExportSource
{
    private ExportSource(bool gameOwned,string? guid,string? hash){IsGameOwned=gameOwned;AssetGuid=guid;SourceHash=hash;}
    /// <summary>Explicit declaration by the game-owned inventory producer.</summary>
    public static ExportSource GameOwned {get;}=new(true,null,null);
    /// <summary>Explicit generated-output provenance bound to an admitted source manifest.</summary>
    public static ExportSource BuiltFrom(string sourceManifestHash)
    {if(!Hex(sourceManifestHash,64))throw new ArgumentException("Expected a source manifest SHA-256.");return new(true,null,sourceManifestHash);}
    /// <summary>Whether the producer declares this to be generated project-data output.</summary>
    public bool IsGameOwned {get;}
    /// <summary>Catalog source identity, or null for GameOwned.</summary>
    public string? AssetGuid {get;}
    /// <summary>Pinned catalog source hash, or admitted source-manifest hash for generated build output; not the output artifact hash.</summary>
    public string? SourceHash {get;}
    /// <summary>Declares a catalog source; invalid identities refuse construction.</summary>
    public static ExportSource Catalog(string guid,string sourceHash)
    {
        if(!Hex(guid,32)||!Hex(sourceHash,64))throw new ArgumentException("Expected a lowercase catalog GUID and source SHA-256.");
        return new(false,guid,sourceHash);
    }
    private static bool Hex(string? text,int length)=>text?.Length==length && text.All(c=>c is >= '0' and <= '9' or >= 'a' and <= 'f');
}
/// <summary>Attribution that the export notice stage must retain; not a generated legal agreement.</summary>
public sealed record ExportOriginNotice(string AssetGuid,string Author,string Origin,string Licence);
/// <summary>Immutable pure review result; only ExportOriginReview can issue it. Hashes identify inputs, not authentication.</summary>
public sealed class ExportOriginReceipt
{
    internal ExportOriginReceipt(string hash,ImmutableArray<string> refusals,ImmutableArray<ExportOriginNotice> notices)
    {ManifestHash=hash;Refusals=refusals;Notices=notices;}
    /// <summary>Exact manifest including artifact source mappings.</summary>
    public string ManifestHash {get;}
    /// <summary>All refused artifact/source reasons, in manifest order.</summary>
    public ImmutableArray<string> Refusals {get;}
    /// <summary>Required licensed-source attribution for the later notice stage.</summary>
    public ImmutableArray<ExportOriginNotice> Notices {get;}
    /// <summary>Every declared artifact source passed this bounded review.</summary>
    public bool Accepted=>Refusals.IsEmpty;
}
/// <summary>Pure review over caller-pinned producing records. No folder scan, asset read, AI-use override or manual approval.</summary>
public static class ExportOriginReview
{
    private static readonly ImmutableHashSet<string> Licences=ImmutableHashSet.Create(StringComparer.Ordinal,
        "CC0-1.0","CC-BY-3.0","CC-BY-4.0","MIT","Zlib","Apache-2.0","BSD-2-Clause","BSD-3-Clause","OFL-1.1");
    /// <summary>Reviews explicit source mappings against copied metadata supplied by the admitted game producer.
    /// The caller supplies the records that produced the pinned artifacts, not live path guesses. Own names are
    /// the existing project's declared rights holders, not an override created by this review.</summary>
    public static ExportOriginReceipt Evaluate(GameContentManifest manifest,IEnumerable<AssetRecord> sourceRecords,IReadOnlyCollection<string>? ownNames=null)
    {
        ArgumentNullException.ThrowIfNull(manifest);ArgumentNullException.ThrowIfNull(sourceRecords);
        var records=sourceRecords.Take(1025).ToArray();
        var refused=ImmutableArray.CreateBuilder<string>();var notices=ImmutableArray.CreateBuilder<ExportOriginNotice>();
        if(records.Length>1024 || records.Any(r=>r is null))
            return new(manifest.Hash,["Source record inventory is missing a record or exceeds 1024 entries."],[]);
        // Copy mutable tag collections before evaluating; no file or scanner invocation.
        var pinned=records.Select(r=>r with {RightsFound=r.RightsFound?.ToArray()}).ToArray();
        var names=ownNames?.ToArray();
        foreach(var node in manifest.Nodes)
        {
            var id=node.Output.InputId;var source=node.Source;
            if(source is null){refused.Add($"{id}: artifact source is not declared.");continue;}
            if(source.IsGameOwned)continue;
            var matches=pinned.Where(r=>r.Guid==source.AssetGuid).ToArray();
            if(matches.Length!=1){refused.Add($"{id}: source {source.AssetGuid} is missing or ambiguous.");continue;}
            var record=matches[0];var p=record.Provenance;
            if(record.SourceHash!=source.SourceHash)refused.Add($"{id}: source hash differs from the producing record.");
            if(record.RightsUnread is not null)refused.Add($"{id}: source rights were not completely read: {record.RightsUnread}");
            if(p is null){refused.Add($"{id}: source provenance is missing.");continue;}
            foreach(var issue in AssetOrigins.Judge(p,record.RightsFound??[],names,record.Guid,record.RightsUnread))
                refused.Add($"{id}: {issue.Message}");
            switch(p.Declared)
            {
                case AssetOrigin.Ours:break;
                case AssetOrigin.PublicDomain:
                    if(string.IsNullOrWhiteSpace(p.Origin))refused.Add($"{id}: public-domain source has no origin.");
                    break;
                case AssetOrigin.Licensed:
                    if(!Licences.Contains(p.Licence??""))refused.Add($"{id}: licence not known to allow redistribution: {p.Licence}");
                    if(string.IsNullOrWhiteSpace(p.Author)||string.IsNullOrWhiteSpace(p.Origin))refused.Add($"{id}: licensed source needs author and origin for its notice.");
                    else if(Licences.Contains(p.Licence??""))notices.Add(new(record.Guid,p.Author,p.Origin,p.Licence??""));
                    break;
                default:refused.Add($"{id}: source origin is undeclared.");break;
            }
        }
        return new(manifest.Hash,refused.ToImmutable(),notices.Distinct().OrderBy(n=>n.AssetGuid,StringComparer.Ordinal).ToImmutableArray());
    }
}

